//! Determinism evidence for the synthetic dataset generator.
//!
//! [`generate_dataset`](crate::generate_dataset) promises byte-identical output
//! for a given `(size, seed)`. A promise is not evidence, so this module hashes
//! the generated bytes with SHA-256 under a canonical, length-prefixed encoding
//! and can record and re-check the result in a committed artifact.
//!
//! # Encoding
//!
//! The digest is
//!
//! ```text
//! SHA-256( "CLIMB dataset v1\0"
//!        || u64_be(message_count)
//!        || for each message: u32_be(len) || message_bytes )
//! ```
//!
//! Length prefixes make the encoding injective: without them, concatenating
//! the messages would let `["ab", "c"]` and `["a", "bc"]` hash identically. The
//! domain string keeps these digests from being confused with any other hash in
//! the project.
//!
//! # No cryptography is added
//!
//! SHA-256 is used only as a collision-resistant checksum over already-generated
//! bytes. It does not replace, wrap, or alter any signature primitive.

use sha2::{Digest, Sha256};

use crate::dataset::{for_each_message, DatasetSize};
use crate::error::DnsError;

/// Schema version of the committed digest document.
pub const DATASET_DIGEST_SCHEMA: u32 = 1;

/// Hash algorithm named in the digest document.
pub const DATASET_DIGEST_ALGORITHM: &str = "sha256";

/// Human-readable description of the encoding, stored in the document so a
/// reader does not have to reverse-engineer it.
pub const DATASET_DIGEST_ENCODING: &str =
    "sha256(\"CLIMB dataset v1\\0\" || u64_be(count) || each(u32_be(len) || message))";

/// Largest dataset the routine determinism gate recomputes by default.
///
/// Small, OneK and Medium together cost well under a second; regenerating a
/// million messages on every validation run does not. The Large entry stays in
/// the committed document and is recomputed on request
/// (`cargo xtask verify-numbers --deep-digests`).
pub const ROUTINE_DIGEST_MAX_COUNT: usize = 10_000;

const DOMAIN: &[u8] = b"CLIMB dataset v1\0";

/// SHA-256 of the deterministic dataset for `size` and `seed`.
#[must_use]
pub fn dataset_digest(size: DatasetSize, seed: u64) -> [u8; 32] {
    dataset_digest_count(size.count(), seed)
}

/// SHA-256 of the first `count` deterministic messages for `seed`.
///
/// Streams the messages instead of materialising the whole dataset, so a
/// million-message digest costs constant memory.
#[must_use]
pub fn dataset_digest_count(count: usize, seed: u64) -> [u8; 32] {
    let mut hasher = Sha256::new();
    hasher.update(DOMAIN);
    hasher.update((count as u64).to_be_bytes());
    for_each_message(count, seed, |message| {
        hasher.update((message.len() as u32).to_be_bytes());
        hasher.update(&message);
    });
    hasher.finalize().into()
}

/// Format a digest as lowercase hexadecimal.
#[must_use]
pub fn digest_hex(digest: &[u8; 32]) -> String {
    let mut out = String::with_capacity(64);
    for byte in digest {
        use std::fmt::Write as _;
        let _ = write!(out, "{byte:02x}");
    }
    out
}

/// One recorded dataset digest.
#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct DatasetDigestEntry {
    /// Dataset size label (`Small`, `OneK`, `Medium`, `Large`).
    pub size: String,
    /// Number of messages in the dataset.
    pub count: usize,
    /// SHA-256 under the encoding named by the document.
    pub digest: String,
}

/// What a digest check actually re-derived.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DigestCheckOutcome {
    /// Number of entries whose digest was recomputed and matched.
    pub checked: usize,
    /// Size labels that were structurally valid but not recomputed because
    /// they exceeded the caller's length limit.
    pub skipped: Vec<String>,
}

/// A committed record of dataset digests, re-checkable by a gate.
#[derive(Clone, Debug, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct DatasetDigestDocument {
    /// Schema version; see [`DATASET_DIGEST_SCHEMA`].
    pub schema: u32,
    /// Hash algorithm; see [`DATASET_DIGEST_ALGORITHM`].
    pub algorithm: String,
    /// Encoding description; see [`DATASET_DIGEST_ENCODING`].
    pub encoding: String,
    /// Seed every entry was generated from.
    pub seed: u64,
    /// One entry per dataset size.
    pub digests: Vec<DatasetDigestEntry>,
}

impl DatasetDigestDocument {
    /// Generate a document for `sizes` at `seed`.
    #[must_use]
    pub fn generate(seed: u64, sizes: &[DatasetSize]) -> Self {
        let digests = sizes
            .iter()
            .map(|size| DatasetDigestEntry {
                size: size.label().to_string(),
                count: size.count(),
                digest: digest_hex(&dataset_digest(*size, seed)),
            })
            .collect();
        Self {
            schema: DATASET_DIGEST_SCHEMA,
            algorithm: DATASET_DIGEST_ALGORITHM.to_string(),
            encoding: DATASET_DIGEST_ENCODING.to_string(),
            seed,
            digests,
        }
    }

    /// Recompute every recorded digest and require it to match.
    ///
    /// # Errors
    ///
    /// See [`check_limited`](Self::check_limited).
    pub fn check(&self, expected_seed: u64) -> Result<(), DnsError> {
        self.check_limited(expected_seed, usize::MAX).map(|_| ())
    }

    /// Recompute every recorded digest up to `max_count`, reporting the rest.
    ///
    /// `expected_seed` is the seed the caller's other artifacts were generated
    /// with; a document from a different seed is rejected rather than compared
    /// against unrelated bytes. Header fields and duplicate labels are checked
    /// for every entry, including those skipped for length.
    ///
    /// # Errors
    ///
    /// Returns [`DnsError::DigestSchema`], [`DnsError::DigestAlgorithm`],
    /// [`DnsError::DigestEncoding`], [`DnsError::DigestSeed`],
    /// [`DnsError::DuplicateDigestSize`] or [`DnsError::DigestMismatch`].
    pub fn check_limited(
        &self,
        expected_seed: u64,
        max_count: usize,
    ) -> Result<DigestCheckOutcome, DnsError> {
        if self.schema != DATASET_DIGEST_SCHEMA {
            return Err(DnsError::DigestSchema {
                schema: self.schema,
                expected: DATASET_DIGEST_SCHEMA,
            });
        }
        if self.algorithm != DATASET_DIGEST_ALGORITHM {
            return Err(DnsError::DigestAlgorithm {
                algorithm: self.algorithm.clone(),
            });
        }
        if self.encoding != DATASET_DIGEST_ENCODING {
            return Err(DnsError::DigestEncoding);
        }
        if self.seed != expected_seed {
            return Err(DnsError::DigestSeed {
                found: self.seed,
                expected: expected_seed,
            });
        }

        let mut outcome = DigestCheckOutcome {
            checked: 0,
            skipped: Vec::new(),
        };
        for (index, entry) in self.digests.iter().enumerate() {
            if self
                .digests
                .iter()
                .take(index)
                .any(|earlier| earlier.size == entry.size)
            {
                return Err(DnsError::DuplicateDigestSize {
                    size: entry.size.clone(),
                });
            }
            if entry.count > max_count {
                outcome.skipped.push(entry.size.clone());
                continue;
            }
            let recomputed = digest_hex(&dataset_digest_count(entry.count, self.seed));
            if recomputed != entry.digest {
                return Err(DnsError::DigestMismatch {
                    size: entry.size.clone(),
                    count: entry.count,
                    seed: self.seed,
                    recorded: entry.digest.clone(),
                    recomputed,
                });
            }
            outcome.checked += 1;
        }
        Ok(outcome)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::generate_dataset_count;

    /// Independent re-implementation of the documented encoding, written here
    /// from the specification rather than by calling `dataset_digest_count`.
    fn expected_digest(messages: &[Vec<u8>]) -> [u8; 32] {
        let mut hasher = Sha256::new();
        hasher.update(b"CLIMB dataset v1\0");
        hasher.update((messages.len() as u64).to_be_bytes());
        for message in messages {
            hasher.update((message.len() as u32).to_be_bytes());
            hasher.update(message);
        }
        hasher.finalize().into()
    }

    #[test]
    fn digest_matches_an_independent_encoding() {
        for count in [0usize, 1, 2, 7, 33] {
            let dataset = generate_dataset_count(count, 42);
            assert_eq!(
                dataset_digest_count(count, 42),
                expected_digest(&dataset),
                "count={count}"
            );
        }
    }

    #[test]
    fn dataset_digest_and_count_agree() {
        for size in DatasetSize::all() {
            if size.count() > 1_000 {
                continue; // keep the unit test fast; the artifact covers the rest
            }
            assert_eq!(
                dataset_digest(size, 7),
                dataset_digest_count(size.count(), 7),
                "size={:?}",
                size
            );
        }
    }

    #[test]
    fn digest_is_deterministic() {
        assert_eq!(
            dataset_digest(DatasetSize::Small, 42),
            dataset_digest(DatasetSize::Small, 42)
        );
    }

    #[test]
    fn different_seeds_have_different_digests() {
        assert_ne!(
            dataset_digest(DatasetSize::Small, 1),
            dataset_digest(DatasetSize::Small, 999)
        );
    }

    #[test]
    fn different_counts_have_different_digests() {
        assert_ne!(
            dataset_digest_count(3, 1),
            dataset_digest_count(4, 1),
            "the count prefix must separate a dataset from its prefix"
        );
    }

    #[test]
    fn length_prefixes_prevent_message_boundary_collisions() {
        let a = vec![b"ab".to_vec(), b"c".to_vec()];
        let b = vec![b"a".to_vec(), b"bc".to_vec()];
        assert_ne!(expected_digest(&a), expected_digest(&b));
    }

    #[test]
    fn document_round_trips_and_checks() {
        let document =
            DatasetDigestDocument::generate(42, &[DatasetSize::Small, DatasetSize::OneK]);
        let json = serde_json::to_string(&document).expect("serialize");
        let parsed: DatasetDigestDocument = serde_json::from_str(&json).expect("parse");
        assert_eq!(parsed, document);
        parsed.check(42).expect("digests match");
    }

    #[test]
    fn document_rejects_a_stale_digest() {
        let mut document = DatasetDigestDocument::generate(42, &[DatasetSize::Small]);
        document.digests[0].digest = "0".repeat(64);
        let error = document.check(42).expect_err("stale digest must fail");
        assert!(matches!(error, DnsError::DigestMismatch { .. }));
    }

    #[test]
    fn document_rejects_a_different_seed() {
        let document = DatasetDigestDocument::generate(42, &[DatasetSize::Small]);
        let error = document.check(43).expect_err("seed mismatch must fail");
        assert!(matches!(error, DnsError::DigestSeed { .. }));
    }

    #[test]
    fn document_rejects_an_unsupported_schema() {
        let mut document = DatasetDigestDocument::generate(42, &[DatasetSize::Small]);
        document.schema = DATASET_DIGEST_SCHEMA + 1;
        assert!(matches!(
            document.check(42),
            Err(DnsError::DigestSchema { .. })
        ));
    }

    #[test]
    fn document_rejects_duplicate_sizes() {
        let mut document = DatasetDigestDocument::generate(42, &[DatasetSize::Small]);
        let duplicate = document.digests[0].clone();
        document.digests.push(duplicate);
        assert!(matches!(
            document.check(42),
            Err(DnsError::DuplicateDigestSize { .. })
        ));
    }

    #[test]
    fn labels_are_stable() {
        assert_eq!(DatasetSize::Small.label(), "Small");
        assert_eq!(DatasetSize::OneK.label(), "OneK");
        assert_eq!(DatasetSize::Medium.label(), "Medium");
        assert_eq!(DatasetSize::Large.label(), "Large");
    }
}
